from __future__ import annotations

import random
from dataclasses import dataclass
from typing import Dict, List, Tuple

Color = Tuple[float, float, float, float]

@dataclass(frozen=True)
class WeaponProfile:
    name: str
    damage: float
    magazine: int
    reserve: int
    fire_interval: float
    reload_time: float
    spread: float
    recoil: float
    accent: Color

@dataclass(frozen=True)
class EnemyProfile:
    name: str
    health: float
    speed: float
    damage: float
    fire_interval: float
    scale: float
    primary: Color
    secondary: Color

@dataclass(frozen=True)
class VehicleProfile:
    name: str
    cruise_speed: float
    aggression: float
    width: float
    length: float
    primary: Color
    secondary: Color

@dataclass(frozen=True)
class RunnerPattern:
    name: str
    difficulty: int
    spacing: float
    lanes: Tuple[int, ...]
    obstacle_types: Tuple[str, ...]
    shard_count: int
    drone_chance: float

@dataclass(frozen=True)
class SpaceFormation:
    name: str
    difficulty: int
    offsets: Tuple[Tuple[float, float, float], ...]
    kinds: Tuple[str, ...]
    speed_multiplier: float
    fire_multiplier: float

@dataclass(frozen=True)
class ArenaLayout:
    name: str
    obstacles: Tuple[Tuple[float, float, float, float, float], ...]
    spawn_points: Tuple[Tuple[float, float, float], ...]
    light_points: Tuple[Tuple[float, float, float], ...]

