def weapon_for_level(level: int) -> WeaponProfile:
    index = max(0, min(len(NEON_WEAPONS) - 1, int(level) * 3 + int(level) // 2))
    return NEON_WEAPONS[index]

def neon_enemy_for_wave(wave: int, elite: bool = False) -> EnemyProfile:
    base = max(0, int(wave) * (3 if elite else 2))
    jitter = random.randint(0, 7 if elite else 4)
    index = min(len(NEON_ENEMIES) - 1, base + jitter + (28 if elite else 0))
    return NEON_ENEMIES[index]

def traffic_for_distance(distance: float) -> VehicleProfile:
    tier = min(len(TRAFFIC_VEHICLES) - 1, int(max(0.0, distance) / 180.0))
    low = max(0, tier - 8)
    high = min(len(TRAFFIC_VEHICLES) - 1, tier + 8)
    return TRAFFIC_VEHICLES[random.randint(low, high)]

def zombie_for_wave(wave: int) -> EnemyProfile:
    tier = min(len(ZOMBIE_ARCHETYPES) - 1, max(0, int(wave) * 4 + random.randint(0, 7)))
    return ZOMBIE_ARCHETYPES[tier]

def runner_pattern_for_distance(distance: float) -> RunnerPattern:
    difficulty = max(1, min(6, 1 + int(max(0.0, distance) / 900.0)))
    candidates = [item for item in RUNNER_PATTERNS if item.difficulty <= difficulty]
    return random.choice(candidates or RUNNER_PATTERNS[:1])

def space_formation_for_wave(wave: int) -> SpaceFormation:
    difficulty = max(1, min(7, 1 + int(wave) // 3))
    candidates = [item for item in SPACE_FORMATIONS if item.difficulty <= difficulty]
    return random.choice(candidates or SPACE_FORMATIONS[:1])

def arena_for_seed(seed: int) -> ArenaLayout:
    return NEON_ARENAS[abs(int(seed)) % len(NEON_ARENAS)]

CONTENT_COUNTS: Dict[str, int] = {
    "weapons": len(NEON_WEAPONS),
    "neon_enemies": len(NEON_ENEMIES),
    "traffic_vehicles": len(TRAFFIC_VEHICLES),
    "zombie_archetypes": len(ZOMBIE_ARCHETYPES),
    "runner_patterns": len(RUNNER_PATTERNS),
    "space_formations": len(SPACE_FORMATIONS),
    "arena_layouts": len(NEON_ARENAS),
}

